export function horizontalPath(id,start,end,pos,e){if(equal(start,end))return[];const bound=e.bounds??SIZES[e.size],f=footprint(BY_ID[id]),xs=new Set([start.x,end.x,0,bound.w-f.w]),zs=new Set([start.z,end.z,0,bound.d-f.d]);for(const other of BODIES){if(other.id===id)continue;for(const q of boxes(other.id,pos[other.id]))if(q.max[1]+CLEARANCE>start.y&&q.min[1]-CLEARANCE<start.y+HEIGHT){xs.add(q.min[0]-f.w-.4);xs.add(q.max[0]+.4);zs.add(q.min[2]-f.d-.4);zs.add(q.max[2]+.4);}}for(const q of obstaclesFor(e))if(q.max[1]+CLEARANCE>start.y&&q.min[1]-CLEARANCE<start.y+HEIGHT){xs.add(q.min[0]-f.w-.4);xs.add(q.max[0]+.4);zs.add(q.min[2]-f.d-.4);zs.add(q.max[2]+.4);}const norm=s=>[...new Set([...s].map(v=>Math.round(v*1e6)/1e6))],xx=norm(xs).filter(x=>x>=-1e-6&&x+f.w<=bound.w+1e-6).sort((a,b)=>a-b),zz=norm(zs).filter(z=>z>=-1e-6&&z+f.d<=bound.d+1e-6).sort((a,b)=>a-b),key=(x,z)=>`${x.toFixed(5)},${z.toFixed(5)}`,nodes=new Map();for(const x of xx)for(const z of zz){const p={...start,x,y:start.y,z};if(moveIsClear(id,p,p,pos,e))nodes.set(key(x,z),p);}const src=key(start.x,start.z),dst=key(end.x,end.z);if(!nodes.has(src)||!nodes.has(dst))throw Error(`${id}: デッキの開始・到着占有が成立しません`);const dist=new Map([[src,0]]),prev=new Map(),open=new Set([src]);while(open.size){const k=[...open].sort((a,b)=>dist.get(a)-dist.get(b))[0];open.delete(k);if(k===dst)break;const p=nodes.get(k),xi=xx.indexOf(p.x),zi=zz.indexOf(p.z);for(const[nx,nz]of[[xi-1,zi],[xi+1,zi],[xi,zi-1],[xi,zi+1]]){if(nx<0||nx>=xx.length||nz<0||nz>=zz.length)continue;const nk=key(xx[nx],zz[nz]),q=nodes.get(nk);if(!q||!moveIsClear(id,p,q,pos,e))continue;const nd=dist.get(k)+Math.abs(q.x-p.x)+Math.abs(q.z-p.z);if(nd<(dist.get(nk)??Infinity)-1e-7){dist.set(nk,nd);prev.set(nk,k);open.add(nk);}}}if(!dist.has(dst))throw Error(`${id}: 保管体・一時退避体を避ける水平経路なし`);const route=[];for(let k=dst;k!==src;k=prev.get(k))route.unshift(nodes.get(k));return route;}
