export const PLANNER_VERSION='stage13-atrium-rooms-1';
export const planMetrics={searches:0,cacheHits:0,invalidations:0,primed:0};
export const planningFingerprint=()=>JSON.stringify([PLANNER_VERSION,BODIES,FIXED,SIZES,ROTATION_BAY,TRANSPORT_POLICY,['A','B','C'].map(p=>placements(p))]);
